package edu.pe.cibertec.saibm.inventario.rest;
import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*; import java.time.*; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.autoconfigure.web.servlet.*; import org.springframework.boot.test.mock.mockito.*; import org.springframework.context.annotation.Import; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import edu.pe.cibertec.saibm.inventario.application.port.in.InventoryUseCase; import edu.pe.cibertec.saibm.inventario.domain.model.InventoryState; import edu.pe.cibertec.saibm.inventario.infrastructure.in.rest.*;
@WebMvcTest(InventoryController.class) @Import(InventoryExceptionHandler.class) class InventoryRestTest { @Autowired MockMvc mvc; @MockBean InventoryUseCase use; @MockBean TransitionalWriteAuthorizer auth; @Test void writesFailClosedWithoutSignedBoundary() throws Exception {doThrow(new WriteAuthorizationException()).when(auth).require(any());mvc.perform(post("/api/v1/inventory/book-7/hold").contentType(MediaType.APPLICATION_JSON).content("{\"quantity\":1,\"expiresAt\":\"2030-01-01T00:00:00Z\"}")).andExpect(status().isForbidden()).andExpect(jsonPath("$.status").value(403));} @Test void holdReturnsVersionedInventoryView() throws Exception {when(use.hold(eq("book-7"),eq(1),any(),eq("k"),any())).thenReturn(new InventoryUseCase.Outcome(new InventoryUseCase.View("k","book-7",1,InventoryState.HELD,Instant.parse("2030-01-01T00:00:00Z")),true));mvc.perform(post("/api/v1/inventory/book-7/hold").header("Idempotency-Key","k").header("X-SAIBM-Write-Timestamp", "1").contentType(MediaType.APPLICATION_JSON).content("{\"quantity\":1,\"expiresAt\":\"2030-01-01T00:00:00Z\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.state").value("HELD"));} }
